'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var join = require( 'path' ).join;
var dirname = require( 'path' ).dirname;
var readFileSync = require( 'fs' ).readFileSync;
var writeFileSync = require( 'fs' ).writeFileSync;
var unlinkSync = require( 'fs' ).unlinkSync;
var mkdirSync = require( 'fs' ).mkdirSync;
var rmdirSync = require( 'fs' ).rmdirSync;
var existsSync = require( 'fs' ).existsSync;
var readdirSync = require( 'fs' ).readdirSync;
var statSync = require( 'fs' ).statSync;
var exec = require( 'child_process' ).exec;
var logger = require( 'debug' );
var now = require( '@stdlib/time/now' );
var format = require( '@stdlib/string/format' );
var dirname = require( '@stdlib/utils/dirname' );
var extractExamples = require( './extract_examples.js' );
var generateTestProgram = require( './generate_test_program.js' );
var resolveIncludes = require( './resolve_includes.js' );
var validate = require( './validate.js' );
var DEFAULTS = require( './defaults.json' );
var compareValues = require( '@stdlib/_tools/doctest/compare-values' );
var createAnnotationValue = require( '@stdlib/_tools/doctest/create-annotation-value' );


// VARIABLES //

var debug = logger( 'c-doctest' );

// Tag prefix for doctest result output lines:
var RESULT_TAG = '__DOCTEST_RESULT__:';

// Regular expression to detect `static` function definitions with JSDoc @example blocks.
// We look for a JSDoc comment containing @example followed by a `static` function:
var RE_STATIC_FUNC = /^\s*static\s+(?:(?:unsigned|signed|long|short)\s+)?(?:double\s+complex|float\s+complex|double|float|int|int8_t|int16_t|int32_t|int64_t|uint8_t|uint16_t|uint32_t|uint64_t|bool|size_t|char|void)\s+\w+\s*\(/;


// MAIN //

/**
* Runs C documentation tests extracted from source files.
*
* @param {Options} options - options
* @param {StringArray} options.files - list of source file paths to test
* @param {string} [options.compiler='gcc'] - C compiler to use
* @param {Array} [options.flags] - compiler flags
* @param {Array} [options.libraries] - libraries to link
* @param {Array} [options.include] - include directories
* @param {Array} [options.libpath] - library paths
* @param {Array} [options.sourceFiles] - additional source files
* @param {boolean} [options.verbose=true] - verbose output
* @param {NonNegativeInteger} [options.timeout=60000] - maximum number of milliseconds allotted for compilation and execution
* @param {PositiveInteger} [options.maxBuffer=10485760] - maximum buffer size for `stdout` and `stderr`
* @param {Callback} clbk - callback to invoke upon completion
* @throws {TypeError} options argument must be an object
* @throws {TypeError} must provide valid options
*/
function cdoctest( options, clbk ) {
	var results;
	var opts;
	var err;

	opts = {};
	opts.compiler = DEFAULTS.compiler;
	opts.flags = DEFAULTS.flags.slice();
	opts.libraries = DEFAULTS.libraries.slice();
	opts.include = DEFAULTS.include.slice();
	opts.libpath = DEFAULTS.libpath.slice();
	opts.sourceFiles = DEFAULTS.sourceFiles.slice();
	opts.verbose = DEFAULTS.verbose;
	opts.timeout = DEFAULTS.timeout;
	opts.maxBuffer = DEFAULTS.maxBuffer;

	err = validate( opts, options );
	if ( err ) {
		throw err;
	}

	results = {
		'total': 0,
		'pass': 0,
		'fail': 0,
		'errors': []
	};

	processFiles( opts.files, 0 );

	/**
	* Processes files sequentially.
	*
	* @private
	* @param {StringArray} files - file list
	* @param {number} idx - current index
	*/
	function processFiles( files, idx ) {
		var resolved;
		var examples;
		var content;
		var fpath;

		if ( idx >= files.length ) {
			return clbk( null, results );
		}
		fpath = resolve( files[ idx ] );
		debug( 'Processing file: %s', fpath );

		try {
			content = readFileSync( fpath, 'utf8' );
		} catch ( err ) {
			debug( 'Unable to read file: %s. Error: %s', fpath, err.message );
			results.errors.push({
				'file': fpath,
				'error': err.message
			});
			return processFiles( files, idx + 1 );
		}

		// Skip Node-API related files:
		if (
			content.indexOf( '#include <node_api.h>' ) !== -1 ||
			content.indexOf( '#include <js_native_api.h>' ) !== -1 ||
			content.indexOf( '#include <node.h>' ) !== -1 ||
			content.indexOf( '#include <v8.h>' ) !== -1
		) {
			debug( 'Skipping Node-API related file: %s', fpath );
			return processFiles( files, idx + 1 );
		}

		// Auto-resolve include directories, source files, libraries, and library paths from the package manifest:
		resolved = resolveIncludes( content, fpath );
		debug( 'Auto-resolved %d include directories for %s.', resolved.includes.length, fpath );
		debug( 'Auto-resolved %d source files for %s.', resolved.sources.length, fpath );
		debug( 'Auto-resolved %d libraries for %s.', resolved.libraries.length, fpath );
		debug( 'Auto-resolved %d library paths for %s.', resolved.libpath.length, fpath );

		// Extract @example blocks from the source file:
		examples = extractExamples( content, fpath );
		debug( 'Found %d @example blocks in %s.', examples.length, fpath );

		if ( examples.length === 0 ) {
			return processFiles( files, idx + 1 );
		}
		processExamples( examples, fpath, content, resolved, 0, function onDone( ) {
			processFiles( files, idx + 1 );
		});
	}

	/**
	* Processes examples from a single file.
	*
	* @private
	* @param {Array} examples - array of example objects
	* @param {string} fpath - file path
	* @param {string} sourceContent - original source file content
	* @param {Object} resolved - auto-resolved manifest data
	* @param {StringArray} resolved.includes - include directories
	* @param {StringArray} resolved.sources - source files
	* @param {StringArray} resolved.libraries - libraries
	* @param {StringArray} resolved.libpath - library paths
	* @param {number} idx - current index
	* @param {Function} done - callback
	*/
	function processExamples( examples, fpath, sourceContent, resolved, idx, done ) {
		var result;
		var tmpDir;
		var srcFile;
		var outFile;
		var example;
		var dir;
		var cmd;

		if ( idx >= examples.length ) {
			return done( );
		}
		example = examples[ idx ];
		results.total += 1;

		debug( 'Processing example %d of %d from %s (line %d)...', idx + 1, examples.length, fpath, example.line );

		if ( opts.verbose ) {
			console.log( '\n---\nRunning doctest from %s (line %d)...\n', fpath, example.line ); // eslint-disable-line no-console
		}

		dir = dirname( fpath );

		// Use Approach A (append-to-source) for all files. This ensures that:
		// 1. We can test internal `static` functions.
		// 2. We avoid `multiple definition` errors at link time (which occur
		//    in Normal mode when headers define data symbols and are included
		//    in both the source file and the doctest file).
		// 3. We have a simpler, more robust unified pipeline.
		var useAppendMode = true;

		// Generate a test program from the example:
		var genOpts = {};

		// Automatically discover the package's own header files
		// (source files typically don't #include their own package header,
		// so the generated doctest code would lack a declaration for the
		// function under test — GCC then assumes int return type → wrong results):
		var pkgHeaders = findPackageHeaders( fpath, resolved.includes );

		if ( useAppendMode ) {
			genOpts.appendMode = true;
		}
		if ( pkgHeaders.length > 0 ) {
			genOpts.extraIncludes = pkgHeaders;
		}
		result = generateTestProgram( example, fpath, sourceContent, genOpts );

		// Create a temporary directory:
		tmpDir = join( dir, '__tmp_c_doctest_' + now( ).toString( ) + '__' );
		try {
			mkdirSync( tmpDir, { 'recursive': true } );
		} catch ( err ) {
			results.fail += 1;
			results.errors.push({
				'file': fpath,
				'line': example.line,
				'error': format( 'Unable to create temporary directory. Error: %s', err.message )
			});
			return processExamples( examples, fpath, sourceContent, resolved, idx + 1, done );
		}

		outFile = join( tmpDir, 'doctest.out' );

		if ( useAppendMode ) {
			// Approach A: append doctest main() to a temp copy of the source file,
			// then compile the temp copy in place of the original:
			srcFile = join( tmpDir, 'doctest_main.c' );
			try {
				// We use #line directives so that GCC reports errors relative to the original source file:
				var composite = '#line 1 "' + fpath + '"\n' + sourceContent +
								'\n#line ' + ( example.line + 1 ) + ' "' + fpath + '"\n' +
								result.program;
				writeFileSync( srcFile, composite );
			} catch ( err ) {
				cleanup( tmpDir, srcFile, outFile );
				results.fail += 1;
				results.errors.push({
					'file': fpath,
					'line': example.line,
					'error': format( 'Unable to write temporary file. Error: %s', err.message )
				});
				return processExamples( examples, fpath, sourceContent, resolved, idx + 1, done );
			}
			// Build compile command, replacing the original source with the temp copy:
			cmd = buildCompileCommand( null, outFile, resolved, fpath, srcFile );
		} else {
			// Normal mode: separate doctest.c file:
			srcFile = join( tmpDir, 'doctest.c' );
			try {
				writeFileSync( srcFile, result.program );
			} catch ( err ) {
				cleanup( tmpDir, srcFile, outFile );
				results.fail += 1;
				results.errors.push({
					'file': fpath,
					'line': example.line,
					'error': format( 'Unable to write temporary file. Error: %s', err.message )
				});
				return processExamples( examples, fpath, sourceContent, resolved, idx + 1, done );
			}
			cmd = buildCompileCommand( srcFile, outFile, resolved );
		}
		debug( 'Compile command: %s', cmd );

		exec( cmd, {
			'cwd': dir,
			'maxBuffer': opts.maxBuffer,
			'timeout': opts.timeout
		}, onCompile );

		/**
		* Callback invoked upon completing compilation.
		*
		* @private
		* @param {Error} error - error object
		* @param {Buffer} stdout - standard output
		* @param {Buffer} stderr - standard error
		*/
		function onCompile( error, stdout, stderr ) {
			var filteredErr;
			if ( error ) {
				filteredErr = filterStderr( ( stderr || '' ).toString( ), fpath );
				debug( 'Compilation failed for example at line %d in %s.', example.line, fpath );
				cleanup( tmpDir, srcFile, outFile );
				results.fail += 1;
				results.errors.push({
					'file': fpath,
					'line': example.line,
					'error': format( 'Compilation failed.\n\n%s', filteredErr || stderr.toString( ) )
				});
				return processExamples( examples, fpath, sourceContent, resolved, idx + 1, done );
			}
			debug( 'Compilation succeeded. Running executable...' );

			// Even if compilation succeeded, there might be relevant warnings:
			filteredErr = filterStderr( ( stderr || '' ).toString( ), fpath );
			if ( filteredErr && opts.verbose ) {
				console.error( filteredErr ); // eslint-disable-line no-console
			}

			exec( outFile, {
				'cwd': dir,
				'maxBuffer': opts.maxBuffer,
				'timeout': opts.timeout
			}, onRun );
		}

		/**
		* Callback invoked upon completing execution.
		*
		* @private
		* @param {Error} error - error object
		* @param {Buffer} stdout - standard output
		* @param {Buffer} stderr - standard error
		*/
		function onRun( error, stdout, stderr ) {
			var outputResults;
			var actual;
			var lines;
			var out;
			var msg;
			var i;

			cleanup( tmpDir, srcFile, outFile );

			out = ( stdout || '' ).toString( );

			if ( error ) {
				debug( 'Execution failed for example at line %d in %s.', example.line, fpath );
				results.fail += 1;
				results.errors.push({
					'file': fpath,
					'line': example.line,
					'error': format( 'Execution failed.\n\n%s', ( stderr || '' ).toString( ) || error.message )
				});
				return processExamples( examples, fpath, sourceContent, resolved, idx + 1, done );
			}

			// Parse output for doctest result lines:
			lines = out.split( '\n' );
			outputResults = [];
			for ( i = 0; i < lines.length; i++ ) {
				if ( lines[ i ].indexOf( RESULT_TAG ) === 0 ) {
					outputResults.push( lines[ i ].substring( RESULT_TAG.length ) );
				}
			}

			// Compare each result with its annotation using compareValues:
			for ( i = 0; i < outputResults.length && i < result.annotations.length; i++ ) {
				actual = parseOutputValue( outputResults[ i ] );
				msg = compareValues( actual, result.annotations[ i ].value );
				if ( msg ) {
					debug( 'Doctest assertion failed at line %d in %s: %s', result.annotations[ i ].line, fpath, msg );
					results.fail += 1;
					results.errors.push({
						'file': fpath,
						'line': result.annotations[ i ].line,
						'error': format( 'Doctest assertion failed. %s (annotation: `// returns %s`, actual: `%s`)', msg, result.annotations[ i ].value, createAnnotationValue( actual ) )
					});
					if ( opts.verbose ) {
						console.log( format( 'DOCTEST FAILED: %s', msg ) ); // eslint-disable-line no-console
					}
					return processExamples( examples, fpath, sourceContent, resolved, idx + 1, done );
				}
			}

			debug( 'Doctest passed for example at line %d in %s.', example.line, fpath );
			results.pass += 1;
			if ( opts.verbose ) {
				console.log( 'DOCTEST PASSED' ); // eslint-disable-line no-console
			}
			processExamples( examples, fpath, sourceContent, resolved, idx + 1, done );
		}
	}

	/**
	* Builds a compile command.
	*
	* @private
	* @param {(string|null)} srcFile - doctest source file path (null in append mode)
	* @param {string} outFile - output file path
	* @param {Object} resolved - auto-resolved manifest data
	* @param {StringArray} resolved.includes - auto-resolved include directories
	* @param {StringArray} resolved.sources - auto-resolved source files
	* @param {StringArray} resolved.libraries - auto-resolved libraries
	* @param {StringArray} resolved.libpath - auto-resolved library paths
	* @param {string} [replaceSrc] - original source file path to replace (append mode)
	* @param {string} [replaceWith] - temp file path to replace it with (append mode)
	* @returns {string} compile command
	*/
	function buildCompileCommand( srcFile, outFile, resolved, replaceSrc, replaceWith ) {
		var cmd;
		var src;
		var i;

		cmd = opts.compiler;

		for ( i = 0; i < opts.flags.length; i++ ) {
			cmd += ' ' + opts.flags[ i ];
		}
		// Add auto-resolved include directories first:
		for ( i = 0; i < resolved.includes.length; i++ ) {
			cmd += ' -I ' + resolved.includes[ i ];
		}
		// Then user-provided include directories:
		for ( i = 0; i < opts.include.length; i++ ) {
			cmd += ' -I ' + opts.include[ i ];
		}
		cmd += ' -o ' + outFile;

		// Add auto-resolved source files, replacing the original if in append mode:
		for ( i = 0; i < resolved.sources.length; i++ ) {
			src = resolved.sources[ i ];
			// Use resolve() to normalize both paths so relative vs absolute
			// comparison doesn't fail (Bug 2 fix):
			if ( replaceSrc && resolve( src ) === resolve( replaceSrc ) ) {
				// In append mode, swap the original source for the temp copy:
				cmd += ' ' + replaceWith;
			} else {
				cmd += ' ' + src;
			}
		}
		// Then user-provided source files:
		for ( i = 0; i < opts.sourceFiles.length; i++ ) {
			cmd += ' ' + opts.sourceFiles[ i ];
		}
		// In normal mode, add the doctest source file:
		if ( srcFile ) {
			cmd += ' ' + srcFile;
		}

		// Add auto-resolved library paths first:
		for ( i = 0; i < resolved.libpath.length; i++ ) {
			cmd += ' -L ' + resolved.libpath[ i ];
		}
		// Then user-provided library paths:
		for ( i = 0; i < opts.libpath.length; i++ ) {
			cmd += ' -L ' + opts.libpath[ i ];
		}
		// Add auto-resolved libraries first:
		for ( i = 0; i < resolved.libraries.length; i++ ) {
			cmd += ' ' + resolved.libraries[ i ];
		}
		// Then user-provided libraries:
		for ( i = 0; i < opts.libraries.length; i++ ) {
			cmd += ' ' + opts.libraries[ i ];
		}
		return cmd;
	}
}

/**
* Parses a C program output value string into a JavaScript value.
*
* @private
* @param {string} str - output value string from C printf
* @returns {number} parsed JavaScript value
*/
function parseOutputValue( str ) {
	var lower = str.trim( ).toLowerCase( );
	if ( lower === 'nan' || lower === '-nan' ) {
		return NaN;
	}
	if ( lower === 'inf' || lower === '+inf' || lower === 'infinity' ) {
		return Infinity;
	}
	if ( lower === '-inf' || lower === '-infinity' ) {
		return -Infinity; // eslint-disable-line no-loss-of-precision
	}
	// [Fix 3] Handle bool outputs printed as "true"/"false":
	if ( lower === 'true' ) {
		return true;
	}
	if ( lower === 'false' ) {
		return false;
	}
	return parseFloat( str.trim( ) );
}

/**
* Cleans up temporary files.
*
* @private
* @param {string} tmpDir - temporary directory
* @param {string} srcFile - source file path
* @param {string} outFile - output file path
*/
function cleanup( tmpDir, srcFile, outFile ) {
	try {
		unlinkSync( srcFile );
	} catch ( err ) {
		debug( 'Unable to remove temporary source file: %s', srcFile );
	}
	try {
		unlinkSync( outFile );
	} catch ( err ) {
		debug( 'Unable to remove temporary output file: %s', outFile );
	}
	try {
		rmdirSync( tmpDir );
	} catch ( err ) {
		debug( 'Unable to remove temporary directory: %s', tmpDir );
	}
}

/**
* Checks whether a C source file contains `static` function definitions that
* have `@example` JSDoc blocks. If so, the file should use append-to-source
* mode (Approach A) for doctesting so that static functions are accessible.
*
* @private
* @param {string} content - source file content
* @returns {boolean} true if the file has static functions with @example blocks
*/
function hasStaticExamples( content ) {
	var inComment;
	var hasExample;
	var lines;
	var line;
	var i;

	lines = content.split( '\n' );
	inComment = false;
	hasExample = false;

	for ( i = 0; i < lines.length; i++ ) {
		line = lines[ i ];

		// Track JSDoc comment blocks:
		if ( /\/\*\*/.test( line ) ) {
			inComment = true;
			hasExample = false;
			continue;
		}
		if ( inComment && /\*\//.test( line ) ) {
			inComment = false;
			// The line after `*/` is the function definition.
			// Check the next non-empty line for `static`:
			if ( hasExample ) {
				// Look ahead for the function definition:
				for ( var j = i + 1; j < lines.length && j <= i + 3; j++ ) {
					if ( RE_STATIC_FUNC.test( lines[ j ] ) ) {
						return true;
					}
					if ( lines[ j ].trim( ).length > 0 ) {
						break; // stop at first non-empty non-static line
					}
				}
			}
			hasExample = false;
			continue;
		}
		if ( inComment && /^\s*\*\s*@example\s*$/.test( line ) ) {
			hasExample = true;
		}
	}
	return false;
}

/**
* Filters the compilation output to suppress noise from dependency files.
*
* @private
* @param {string} stderr - compilation output
* @param {string} fpath - path to the file under test
* @returns {string} filtered output
*/
function filterStderr( stderr, fpath ) {
	var filtered;
	var lines;
	var i;

	if ( !stderr ) {
		return '';
	}
	lines = stderr.split( '\n' );
	filtered = [];

	for ( i = 0; i < lines.length; i++ ) {
		// Keep lines that mention the target file (absolute path mapping from #line):
		if ( lines[ i ].indexOf( fpath ) !== -1 ) {
			filtered.push( lines[ i ] );
			// Look ahead to collect associated context lines (code snippets, carats, etc.):
			while ( i + 1 < lines.length &&
				( lines[ i + 1 ].indexOf( '|' ) !== -1 ||
					lines[i + 1].indexOf('^') !== -1 ||
					lines[i + 1].trim().length === 0 ) ) {
				i += 1;
				filtered.push( lines[ i ] );
			}
		} else if ( lines[ i ].indexOf( 'error:' ) !== -1 ) {
			// Keep all errors (they block the build), but only if they are not from a redundant source:
			filtered.push( lines[ i ] );
			while ( i + 1 < lines.length &&
				( lines[ i + 1 ].indexOf( '|' ) !== -1 ||
					lines[i + 1].indexOf('^') !== -1 ||
					lines[i + 1].trim().length === 0) ) {
				i += 1;
				filtered.push( lines[ i ] );
			}
		}
	}
	return filtered.join( '\n' ).trim();
}

/**
* Finds a package's own header files.
*
* @private
* @param {string} fpath - source file path
* @param {StringArray} includes - include directories
* @returns {StringArray} header files (as #include directives)
*/
function findPackageHeaders( fpath, includes ) {
	var headers;
	var dir;

	headers = [];
	if ( includes.length === 0 ) {
		return headers;
	}
	// The first include directory is typically the package's own `include/` directory:
	dir = includes[ 0 ];
	if ( !existsSync( dir ) ) {
		return headers;
	}

	function walk( currentDir, relativePath ) {
		var stats;
		var files;
		var i;

		try {
			files = readdirSync( currentDir );
		} catch ( err ) {
			return;
		}
		for ( i = 0; i < files.length; i++ ) {
			stats = statSync( join( currentDir, files[ i ] ) );
			if ( stats.isDirectory() ) {
				walk( join( currentDir, files[ i ] ), join( relativePath, files[ i ] ) );
			} else if ( /\.h$/.test( files[ i ] ) ) {
				headers.push( '#include "' + join( relativePath, files[ i ] ) + '"' );
			}
		}
	}

	walk( dir, '' );
	return headers;
}


// EXPORTS //

module.exports = cdoctest;
